/** #DML_OPTION_DTMONTH { pk(dt_month) }  **/
if object_id(N'tempdb..#DML_OPTION_DTMONTH', N'U') is not null drop table #DML_OPTION_DTMONTH;
select distinct
	dt_month
into #DML_OPTION_DTMONTH
from DML_CALENDAR
where dt_month = '2025-02-01';

create unique clustered index idx__dm
	on #DML_OPTION_DTMONTH
	   (dt_month);

/** [#DML_売上と原価_OPTION_DTMONTH_DAF4] { pk(dt_month) }  **/
