select distinct
	t2.dt_month
into [#DML_売上と原価_OPTION_DTMONTH_DAF4]
from #DML_OPTION_DTMONTH t1
left join DML_CALENDAR t2
	on t2.dt_month between datefromparts(year(cast(t1.dt_month as date)), 1, 1) and t1.dt_month;

create unique clustered index idx__dm
	on [#DML_売上と原価_OPTION_DTMONTH_DAF4]
	   (dt_month);

/** [DML_売上と原価_BY_DM_地_8F44CC0E] { pk(dt_month, [地域]) }  **/
with [DML_売上と原価_BY_DM_地_8F44CC0E] as (
select
	dt_month,
	region as [地域],
	SUM(revenue_amount) as [純売上高],
	SUM(cost_amount) as [売上原価]
from TABLE_PROFITABILITY
where dt_month in (select dt_month from [#DML_売上と原価_OPTION_DTMONTH_DAF4] [#dml_売上と原価_option_dtmonth_daf4])
group by dt_month,
	region
)

/** MAIN_QUERY { pk(dt_month, [地域]) } **/
select
	/** auto-generated by datoml: qf912bebdec **/
	t2.[地域],
	t1.dt_month,
	((SUM(t2.[純売上高])) - (SUM(t2.[売上原価]))) / nullif((SUM(t2.[純売上高])), 0) as [年初来粗利率]
from #DML_OPTION_DTMONTH t1
inner join [DML_売上と原価_BY_DM_地_8F44CC0E] t2
	on t2.dt_month between datefromparts(year(cast(t1.dt_month as date)), 1, 1) and t1.dt_month
