create unique clustered index idx__dm_地
	on [#DML_売上と原価_BY_DM_地_356DCC0_YTD]
	   (dt_month, 地域);

/** [#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA] { pk(dt_month, 地域) } **/
if object_id(N'tempdb..[#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA]', N'U') is not null drop table [#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA];
select
    t1.dt_month,
    t2.地域,
    SUM(t2.純売上高) as 純売上高,
    SUM(t2.売上原価) as 売上原価,
    (SUM(t2.純売上高) - SUM(t2.売上原価)) / nullif(SUM(t2.純売上高), 0) as [前年同期の年初来粗利率]
into [#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA]
from #DML_OPTION_DTMONTH t1
inner join [#DML_売上と原価_BY_DM_地_8F44CC0E] t2
    on t2.dt_month between dateadd(year, -1, cast(datefromparts(year(cast(t1.dt_month as date)), 1, 1) as date)) and dateadd(year, -1, cast(t1.dt_month as date))
group by t1.dt_month, t2.地域;

create unique clustered index idx__dm_地
	on [#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA]
	   (dt_month, 地域);

/** [DML_売上と原価_BY_DM_地_BA73CC0] { pk(dt_month, 地域) } **/
with [DML_売上と原価_BY_DM_地_BA73CC0] as (
select
    coalesce(t1.dt_month, t2.dt_month) as dt_month,
    coalesce(t1.地域, t2.地域) as 地域,
    100 * (t1.年初来粗利率 - t2.[前年同期の年初来粗利率]) as [粗利率の前年差ポイント]
from [#DML_売上と原価_BY_DM_地_356DCC0_YTD] t1
full outer join [#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA] t2
    on (t2.dt_month = t1.dt_month or (t2.dt_month is null and t1.dt_month is null))
    and (t2.地域 = t1.地域 or (t2.地域 is null and t1.地域 is null))
)


