select
    t.地域,
    t.dt_month,
    t900ce.年初来粗利率,
    t960b5.[前年同期の年初来粗利率],
    t.[粗利率の前年差ポイント]
from [DML_売上と原価_BY_DM_地_BA73CC0] t
left join [#DML_売上と原価_BY_DM_地_356DCC0_YTD] t900ce 
	on (t900ce.dt_month = t.dt_month or (t900ce.dt_month is null and t.dt_month is null))
	and (t900ce.地域 = t.地域 or (t900ce.地域 is null and t.地域 is null))
left join [#DML_売上と原価_BY_DM_地_5322CC0_YTD_YA] t960b5 
	on (t960b5.dt_month = t.dt_month or (t960b5.dt_month is null and t.dt_month is null))
	and (t960b5.地域 = t.地域 or (t960b5.地域 is null and t.地域 is null))
order by t.地域, t.dt_month;
